11	/**
12	 * Loads the content from a file reference
13	 * @param fileRef The file reference string (e.g. 'file://path/to/file.json')
14	 * @param basePath Base path for resolving relative paths
15	 * @returns The loaded content from the file
16	 */
17	export async function loadFileReference(fileRef: string, basePath: string = ''): Promise<any> {
18	  // Parse file:// URL with Windows-aware path handling
19	  const { filePath, functionName } = parseFileUrl(fileRef);
20	
21	  // Resolve the absolute path
22	  const resolvedPath = path.resolve(basePath, filePath);
23	  const extension = path.extname(resolvedPath).toLowerCase();
24	
25	  logger.debug(
26	    `Loading file reference: ${fileRef}, resolvedPath: ${resolvedPath}, extension: ${extension}`,
27	  );
28	
29	  try {
30	    if (extension === '.json') {
31	      logger.debug(`Loading JSON file: ${resolvedPath}`);
32	      const content = await fs.promises.readFile(resolvedPath, 'utf8');
33	      return JSON.parse(content);
34	    } else if (extension === '.yaml' || extension === '.yml') {
35	      logger.debug(`Loading YAML file: ${resolvedPath}`);
36	      const content = await fs.promises.readFile(resolvedPath, 'utf8');
37	      return yaml.load(content);
38	    } else if (isJavascriptFile(resolvedPath)) {
39	      logger.debug(`Loading JavaScript file: ${resolvedPath}`);
40	      const mod = await importModule(resolvedPath, functionName);
41	      return typeof mod === 'function' ? await mod() : mod;
42	    } else if (extension === '.py') {
43	      logger.debug(
44	        `Loading Python file: ${resolvedPath}, function: ${functionName || 'get_config'}`,
45	      );
46	      const fnName = functionName || 'get_config';
